import {WindowMotion,WINDOW_RESIZE_EDGES} from './foundation/window-motion.js';
import {StickyNoteWindowOwner,STICKY_NOTE_WINDOW_OWNER,STICKY_NOTE_WINDOW_PRESENTATION} from './foundation/notes/sticky-note-window.js';
import {LibraryNoteRuntimeComposition} from './adapters/library-note-runtime-composition.js';

const assert=(value,message='assertion failed')=>{if(!value)throw Error(message)};
const pointer=(target,x,y,id=11)=>({button:0,target,clientX:x,clientY:y,pointerId:id,preventDefault(){this.defaultPrevented=true}});
const element=()=>({style:{},setPointerCapture:()=>{},releasePointerCapture:()=>{}});
const handle=edge=>({dataset:{noteResize:edge},closest(selector){return selector==='[data-note-resize]'?this:null}});
const test=(cases,id,run)=>{try{cases.push({id,status:'PASS',detail:run()??null})}catch(error){cases.push({id,status:'FAIL',error:String(error?.message||error)})}};
const viewport={box:{width:1440,height:1000,topInset:8,rightInset:8,bottomInset:8,leftInset:8},read(){return {...this.box}}};

export function runPW11StickyNoteWindowProof(){
  const cases=[];
  test(cases,'pw11.presentation.actual-donor-provenance',()=>{assert(STICKY_NOTE_WINDOW_PRESENTATION.owner===STICKY_NOTE_WINDOW_OWNER);assert(STICKY_NOTE_WINDOW_PRESENTATION.donor.sha256==='ea66b58ef122bf2f8ca23fd0aa9e461b07da11ea7390c451902e4b1592d396fd');assert(STICKY_NOTE_WINDOW_PRESENTATION.resizeHandles.length===8);return STICKY_NOTE_WINDOW_PRESENTATION});
  test(cases,'pw11.pointer.dynamic-all-edge-and-corner-resolution',()=>{for(const edge of WINDOW_RESIZE_EDGES){const owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n',{geometry:{x:300,y:220,width:420,height:330}});const node=element(),motion=new WindowMotion(()=>owner.motionBinding('n',node,{edge:'se'})),target=handle(edge),down=pointer(target,400,300);assert(motion.down(down),`down ${edge}`);motion.move({...down,clientX:edge.includes('left')?430:edge.includes('right')?440:400,clientY:edge.includes('top')?325:edge.includes('bottom')?345:300});assert(motion.up(),`up ${edge}`);assert(motion.receipts.at(-1).edge===edge,`resolved ${edge}`)}return {edges:[...WINDOW_RESIZE_EDGES]}});
  test(cases,'pw11.pointer.legacy-se-alias-remains-bottom-right',()=>{const owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n',{geometry:{x:100,y:100,width:400,height:300}});const node=element(),motion=new WindowMotion(()=>owner.motionBinding('n',node,{edge:'se'})),target={closest:()=>null},down=pointer(target,100,100);assert(motion.down(down));motion.move({...down,clientX:150,clientY:140});motion.up();const g=owner.window('n').geometry;assert(g.width===450&&g.height===340&&motion.receipts.at(-1).edge==='bottom-right');return g});
  test(cases,'pw11.lifecycle.hide-close-is-presentation-only',()=>{const fixture={blocks:[{id:'b',html:'keep'}],binding:{documentId:'KU-D05-0021',blockId:'b'}},before=JSON.stringify(fixture),owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n');const hidden=owner.hide('n');assert(hidden.window.lifecycle==='hidden'&&JSON.stringify(fixture)===before);const receipt=owner.receipts.at(-1);assert(receipt.contentDeleted===false&&receipt.sourceDeleted===false&&receipt.bindingDeleted===false&&receipt.persistenceChanged===false);owner.open('n');assert(owner.window('n').lifecycle==='open');return receipt});
  test(cases,'pw11.pin-never-implies-os-always-on-top',()=>{const owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n');const pinned=owner.setPinned('n',true),request=owner.requestAlwaysOnTop('n',true);assert(pinned.pinned===true&&pinned.platform.alwaysOnTop.active===false);assert(request.ok===false&&request.code==='UNAVAILABLE');return {pinScope:owner.receipts.find(x=>x.action==='window.pin').scope,alwaysOnTop:request.projection}});
  test(cases,'pw11.library-thin-adapter-consumes-window-presentation-owner',()=>{const runtime=new LibraryNoteRuntimeComposition({viewport:()=>viewport.read()});runtime.ensure({id:'note-1',title:'Note',binding:{documentId:'KU-D05-0021',blockId:'b',route:'PERSONAL:CEP/W02/library'},window:{x:120,y:130,width:360,height:320,pinned:false,closed:false},working:{blocks:[]}});const p=runtime.windowPresentation('note-1'),d=runtime.descriptor();assert(p.owner===STICKY_NOTE_WINDOW_OWNER&&p.contentOwner==='StructuredNoteContentAdapter'&&p.semanticOwner===false);assert(p.source.documentId==='KU-D05-0021'&&d.presentationOwner===STICKY_NOTE_WINDOW_OWNER);return {owner:p.owner,contentOwner:p.contentOwner,source:p.source}});
  test(cases,'pw11.viewport-constrained-reachable-and-internal-scroll',()=>{const owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n',{geometry:{x:900,y:700,width:500,height:360}});viewport.box.width=1024;viewport.box.height=900;const w=owner.reclamp('n',{reason:'pw11-1024x900'}),v=w.viewport,o=owner.overflowProjection('n',{contentHeight:1200});assert(w.geometry.x>=v.left&&w.geometry.y>=v.top&&w.geometry.x+w.geometry.width<=v.right&&w.geometry.y+w.geometry.height<=v.bottom);assert(o.internalScrollRequired&&o.bottomToolbarReachable&&o.statusRegionReachable);return {geometry:w.geometry,viewport:v,overflow:o}});
  test(cases,'pw11.keyboard-move-resize-and-accessibility',()=>{const owner=new StickyNoteWindowOwner({viewport:()=>viewport.read()});owner.register('n',{geometry:{x:100,y:100,width:360,height:300}});let prevented=0;const move=owner.keyboardGeometry('n',{altKey:true,shiftKey:false,key:'ArrowRight',preventDefault:()=>prevented++}),resize=owner.keyboardGeometry('n',{altKey:true,shiftKey:true,key:'ArrowDown',preventDefault:()=>prevented++}),a=owner.accessibleActions('n');assert(move.handled&&resize.handled&&prevented===2&&a.resize.edges.length===8&&a.close.effect==='PRESENTATION_ONLY');return {move:move.window.geometry,resize:resize.window.geometry,actions:a}});
  const fail=cases.filter(x=>x.status==='FAIL');return {schemaVersion:1,kind:'PW11_STICKY_NOTE_WINDOW_FOCUSED_PROOF',status:fail.length?'FAIL':'PASS',caseCount:cases.length,passCount:cases.length-fail.length,failCount:fail.length,cases};
}
